import {definition} from './engine.js';
import {pulleyRadius,beltOutline,beltIcon,BELT_REFERENCE} from './belt-parts.js';
import {fitBelt} from './belt-drive.js';
export function beltDialog({model,showDialog,commit,bandId=null}){
 const pulleys=model.parts.filter(p=>pulleyRadius(definition(p))),options=pulleys.map((p,i)=>`<option value="${i}">${definition(p).name} #${model.parts.indexOf(p)+1}</option>`).join('');let result=null;
 showDialog(`<h2>Pulley belt</h2><div id="belt-preview" style="background:#202934;border-radius:8px;min-height:150px"></div><div class="frame-origin"><label>First pulley<select id="belt-first" aria-label="First pulley">${options}</select></label><label>Second pulley<select id="belt-second" aria-label="Second pulley">${options}</select></label></div><p>${beltIcon()} Brown 92001 · 185 mm · 3 × 3 mm</p><p id="belt-result" role="status"></p><button id="belt-apply" class="button full">${bandId?'Refit band':'Fit band'}</button><details><summary>Fit & drive details</summary><p>Use two small or medium Classic hub/pulleys on parallel axles, with grooves in the same plane. Key the pulleys to drive their rods. The open loop turns both in the same direction.</p><p>Belt shape and speed ratio are previews. The supplier's length convention, tension, stretch limits, slip and loaded torque are unverified. After moving a pulley, select its band and open this tool to refit it. No crossed belts or multi-pulley routing yet.</p><a href="${BELT_REFERENCE}" target="_blank" rel="noreferrer">Original pulley guide</a></details>`);
 const root=document.querySelector('#dialog'),$=s=>root.querySelector(s);$('#belt-second').value=pulleys.length>1?'1':'0';
 function refresh(){result=null;$('#belt-preview').innerHTML='';try{if(pulleys.length<2)throw Error('Add two small or medium hub/pulleys first.');result=fitBelt(model,pulleys[Number($('#belt-first').value)].id,pulleys[Number($('#belt-second').value)].id,{bandId});const b=result.band.belt,r=Math.max(...b.radii)+8,points=beltOutline(b),path=points.map((p,i)=>(i?'L':'M')+p.pos.slice(0,2).join(' ')).join(' ')+'Z';$('#belt-preview').innerHTML=`<svg viewBox="${-r} ${-r} ${b.span+2*r} ${2*r}" style="width:100%;height:190px;padding:18px;box-sizing:border-box" role="img" aria-label="Front view of two pulleys joined by an open belt"><path d="${path}" fill="none" stroke="#ba874f" stroke-width="3"/>${b.radii.map((radius,i)=>`<circle cx="${i*b.span}" r="${radius-2}" fill="#596977" stroke="#b9c5cb"/><circle cx="${i*b.span}" r="3.25" fill="#202934"/><path d="M${i*b.span} -${radius*.55}h${radius*.45}" stroke="#e8eef0" stroke-width="2"/>`).join('')}</svg>`;$('#belt-result').textContent=`${result.length.toFixed(1)} mm loop · output ${(b.radii[0]/b.radii[1]).toFixed(2)}× · fit/tension unverified`;}catch(e){$('#belt-result').textContent=e.message;}$('#belt-apply').disabled=!result;}
 $('#belt-first').onchange=refresh;$('#belt-second').onchange=refresh;$('#belt-apply').onclick=()=>{if(result){commit(result.model);root.close();}};refresh();
}
